def solve(s: str) -> bool:
    """Return True if s is a valid IPv4 address.
    Conditions:
    - Four decimal numbers separated by '.'
    - Each number is 0-255 inclusive
    - No leading zeros unless the number is exactly '0'
    - Only digits are allowed in each part
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        # Leading zero check
        if len(part) > 1 and part[0] == '0':
            return False
        # Value range check
        try:
            val = int(part)
        except ValueError:
            return False
        if not (0 <= val <= 255):
            return False
    return True

