from fractions import Fraction

def solve(matrix):
    # Exact determinant via Gaussian elimination with rational arithmetic.
    n = len(matrix)
    if n == 0:
        return 1
    mat = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for k in range(n):
        if mat[k][k] == 0:
            for i in range(k + 1, n):
                if mat[i][k] != 0:
                    mat[k], mat[i] = mat[i], mat[k]
                    det = -det
                    break
            else:
                return 0
        det *= mat[k][k]
        pivot = mat[k][k]
        for i in range(k + 1, n):
            if mat[i][k]:
                f = mat[i][k] / pivot
                for j in range(k, n):
                    mat[i][j] -= f * mat[k][j]
    return int(det)

def solve(meetings):
    # Greedy: repeatedly take the meeting that ends earliest.
    count = 0
    last_end = None
    for s, e in sorted(meetings, key=lambda m: (m[1], m[0])):
        if last_end is None or s >= last_end:
            count += 1
            last_end = e
    return count

