def solve(grid):
    """Count the number of islands in a 2D grid.
    An island is a group of adjacent cells with value 1, connected orthogonally.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows or j < 0 or j >= cols:
                continue
            if visited[i][j] or grid[i][j] != 1:
                continue
            visited[i][j] = True
            stack.extend([(i-1,j),(i+1,j),(i,j-1),(i,j+1)])
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

