def solve(n, edges):
    # Dijkstra: shortest path 0 -> n-1 in undirected graph with positive weights.
    if n <= 0:
        return -1
    if n == 1:
        return 0
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        adj[a].append((b, w))
        adj[b].append((a, w))
    dist = [float('inf')] * n
    dist[0] = 0
    pq = [(0, 0)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
